from collections import deque
def transform(g):
    h,w=len(g),len(g[0])
    # markers
    comp=[[-1]*w for _ in range(h)]
    cid=0; compcol={}
    for r in range(h):
        for c in range(w):
            if g[r][c]!=0 and comp[r][c]==-1:
                q=deque([(r,c)]); comp[r][c]=cid; col=None
                while q:
                    a,b=q.popleft()
                    if g[a][b]!=1: col=g[a][b]
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<h and 0<=y<w and g[x][y]!=0 and comp[x][y]==-1:
                            comp[x][y]=cid; q.append((x,y))
                compcol[cid]=col; cid+=1
    out=[row[:] for row in g]
    for r in range(h):
        for c in range(w):
            if g[r][c]==0: continue
            ok=all(0<=x<h and 0<=y<w and g[x][y]!=0 for x in range(r-1,r+2) for y in range(c-1,c+2))
            if ok: out[r][c]=compcol[comp[r][c]]
    return out
